    "Expense Claim Type":{icon:"📋",summaryAr:"تعريف أنواع المصروفات (مثل: سفر، طعام، مواصلات) لتصنيف المطالبات.",summaryEn:"Define expense types (e.g., Travel, Food, Transport) to classify claims.",stepsAr:["اضغط «نوع جديد»","أدخل الاسم","حدد الحساب المحاسبي","اضغط «حفظ»"],stepsEn:["Click «New Type»","Enter name","Set GL account","Click «Save»"]},
    "Employee Advance":{icon:"💵",summaryAr:"طلب سلفة مالية للموظف مع تحديد المبلغ والغرض.",summaryEn:"Request employee advance with amount and purpose.",stepsAr:["اضغط «سلفة جديدة»","اختر الموظف","أدخل المبلغ والغرض","حدد التاريخ","اضغط «حفظ» ثم «تسجيل»"],stepsEn:["Click «New Advance»","Select employee","Enter amount and purpose","Set date","Click «Save» then «Submit»"]},
