    ]},
    { titleEn:"Reports", titleAr:"التقارير", icon:"📊", color:"#0891b2", items:[
      { doctype:"Sales Analytics Report",icon:"📑",labelAr:"تقرير تحليل المبيعات",labelEn:"Tax Statement Report",isReport:true,cf:{},sfx:null,color:"#0891b2",
        dAr:"تقرير تحليلي يعرض بيانات المبيعات مع مقارنة شهرية.",dEn:"Analytical report showing sales data with monthly.",
        sAr:["اذهب إلى التقرير","حدد الشركة والفترة","اضغط «تشغيل»","صدّر إلى Excel أو PDF"],
        sEn:["Go to report","Set company and period","Click «Run»","Export to Excel or PDF"]},
      { doctype:"All Tax Report",icon:"🧮",labelAr:"تقرير الضرائب",labelEn:"Tax Report",isReport:true,cf:{},sfx:null,color:"#ea580c",
        dAr:"ملخص الضرائب: ضريبة المبيعات والمشتريات والصافي المستحق.",dEn:"Tax summary: sales tax, purchase tax, and net payable.",
