  ───────────────────────────────────────── */

  function translate(name) {
    if (!isArabic) return name;
    if (arabicFallback[name]) return arabicFallback[name];
    if (typeof window.__ === "function") return window.__(name);
    return name;
  }

  function escapeHtml(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }


  /* ─────────────────────────────────────────
     ١٠. مربع التفاصيل (Modal)
  ───────────────────────────────────────── */

  function showInfoModal(data) {
    const title = isArabic ? data.labelAr : data.labelEn;
    const summary = isArabic ? data.summaryAr : data.summaryEn;
    const steps = isArabic ? data.stepsAr : data.stepsEn;
    const hasSteps = Array.isArray(steps) && steps.length > 0;

    const showStepsText = isArabic ? "📖 عرض الخطوات" : "📖 Show Steps";
    const hideStepsText = isArabic ? "📖 إخفاء الخطوات" : "📖 Hide Steps";

    let stepsHtml = "";
    if (hasSteps) {
      stepsHtml = `
        <div class="erp-modal-steps" data-modal-steps>
          <ol class="erp-modal-steps-list">
            ${steps.map((s) => `<li>${escapeHtml(s)}</li>`).join("")}
          </ol>
        </div>`;
    }

    const overlay = document.createElement("div");
    overlay.className = "erp-modal-overlay";
    overlay.setAttribute("dir", isArabic ? "rtl" : "ltr");

    overlay.innerHTML = `
      <div class="erp-modal-box">
        <button type="button" class="erp-modal-close" data-modal-close aria-label="Close">✕</button>
        <div class="erp-modal-header">
          <span class="erp-modal-icon">${data.icon}</span>
          <h3 class="erp-modal-title">${escapeHtml(title)}</h3>
        </div>
        <p class="erp-modal-summary">${escapeHtml(summary)}</p>
        ${hasSteps ? `<button type="button" class="erp-modal-toggle-steps" data-toggle-steps>${showStepsText}</button>` : ""}
        ${stepsHtml}
      </div>`;

    root.appendChild(overlay);
    requestAnimationFrame(() => overlay.classList.add("is-visible"));

    function closeModal() {
      overlay.classList.remove("is-visible");
      overlay.addEventListener("transitionend", () => overlay.remove(), { once: true });
    }

    overlay.querySelector("[data-modal-close]").addEventListener("click", closeModal);
    overlay.addEventListener("click", (e) => { if (e.target === overlay) closeModal(); });

    const toggleBtn = overlay.querySelector("[data-toggle-steps]");
    const stepsContainer = overlay.querySelector("[data-modal-steps]");
    if (toggleBtn && stepsContainer) {
      toggleBtn.addEventListener("click", () => {
        const isShowing = stepsContainer.classList.contains("is-shown");
        stepsContainer.classList.toggle("is-shown");
        toggleBtn.textContent = isShowing ? showStepsText : hideStepsText;
      });
    }
  }


  /* ─────────────────────────────────────────
     ١١. إنشاء أزرار الاختصارات
  ───────────────────────────────────────── */

  function renderQuickActions() {
    if (!quickActions) return;

    const title = isArabic ? "اختصارات سريعة" : "Quick Actions";

    quickActions.innerHTML = `
      <h2 class="erp-section-title">${escapeHtml(title)}</h2>
      <div class="erp-quick-grid">
        ${quickActionButtons.map((btn) => {
          const label = isArabic ? btn.labelAr : btn.labelEn;
          return `
            <button type="button" class="erp-quick-btn"
              data-new-doc="${escapeHtml(btn.doctype)}"
              ${btn.isReport ? 'data-is-report="1"' : ''}
              style="--btn-color: ${btn.color}">
              <span class="erp-quick-icon" aria-hidden="true">${btn.icon}</span>
              <span class="erp-quick-label">${escapeHtml(label)}</span>
            </button>`;
        }).join("")}
      </div>`;

    quickActions.addEventListener("click", (event) => {
      const btn = event.target.closest("[data-new-doc]");
      if (!btn) return;
      const doctype = btn.dataset.newDoc;
      if (!window.frappe) return;

      if (btn.dataset.isReport === "1") {
        frappe.set_route("query-report", doctype);
        return;
      }

      if (typeof frappe.new_doc === "function") {
        frappe.new_doc(doctype);
      }
    });
  }


  /* ─────────────────────────────────────────
     ١٢. إنشاء البطاقات
  ───────────────────────────────────────── */

  function renderSections() {
    root.setAttribute("dir", isArabic ? "rtl" : "ltr");
    root.classList.toggle("erp-dashboard-rtl", isArabic);

    content.innerHTML = sections
      .map((section, sectionIndex) => {
        const sectionName = section[0];
        const sectionCards = section[1];

        const cardsHtml = sectionCards
          .map((card, cardIndex) => {
            const cardName = card[0];
            const icon = card[1];
            const items = card[2];

            const linksHtml = items.map((itemName) => {
              const desc = itemDescriptions[itemName];
              const detailsLabel = isArabic ? "تفاصيل" : "Details";
              const infoBtn = desc
                ? `<button type="button" class="erp-info-link" data-info-item="${escapeHtml(itemName)}">${detailsLabel}</button>`
                : "";

              return `
                <div class="erp-link-row">
                  <button type="button" class="erp-link" data-route-name="${escapeHtml(itemName)}">
                    <span class="erp-link-text">${escapeHtml(translate(itemName))}</span>
                    <span class="erp-link-arrow" aria-hidden="true">${isArabic ? "←" : "→"}</span>
                  </button>
                  ${infoBtn}
                </div>`;
            }).join("");

            return `
              <article class="erp-card tone-${(sectionIndex + cardIndex) % 5}" data-erp-card>
                <button type="button" class="erp-card-heading" data-card-toggle aria-expanded="false">
                  <span class="erp-icon" aria-hidden="true">${icon}</span>
                  <span class="erp-card-title">${escapeHtml(translate(cardName))}</span>
                  <span class="erp-card-chevron" aria-hidden="true">⌄</span>
                </button>
                <div class="erp-card-links">${linksHtml}</div>
              </article>`;
          }).join("");

        return `
          <section class="erp-module-section">
            <h2 class="erp-section-title">${escapeHtml(translate(sectionName))}</h2>
            <div class="erp-dashboard-grid">${cardsHtml}</div>
          </section>`;
      }).join("");
  }


  /* ─────────────────────────────────────────
     ١٣. إنشاء الفوتر
  ───────────────────────────────────────── */

  function renderFooter() {
    if (!footerEl) return;
    const labels = footerInfo.labels;
    const phoneLabel = isArabic ? labels.phoneAr : labels.phoneEn;
    const emailLabel = isArabic ? labels.emailAr : labels.emailEn;
    const websiteLabel = isArabic ? labels.websiteAr : labels.websiteEn;

    footerEl.innerHTML = `
      <div class="erp-footer-inner">
        <div class="erp-footer-item">
          <span class="erp-footer-icon">📞</span>
          <span class="erp-footer-label">${escapeHtml(phoneLabel)}:</span>
          <a href="tel:${footerInfo.phone}" class="erp-footer-link" dir="ltr">${escapeHtml(footerInfo.phone)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">✉️</span>
          <span class="erp-footer-label">${escapeHtml(emailLabel)}:</span>
          <a href="mailto:${footerInfo.email}" class="erp-footer-link">${escapeHtml(footerInfo.email)}</a>
        </div>
        <span class="erp-footer-sep">|</span>
        <div class="erp-footer-item">
          <span class="erp-footer-icon">🌐</span>
          <span class="erp-footer-label">${escapeHtml(websiteLabel)}:</span>
          <a href="https://${footerInfo.website}" class="erp-footer-link" target="_blank" rel="noopener">${escapeHtml(footerInfo.website)}</a>
        </div>
      </div>`;
  }


  /* ─────────────────────────────────────────
     ١٤. فتح الخيار
  ───────────────────────────────────────── */

  function openRoute(name) {
    if (!window.frappe || typeof frappe.set_route !== "function") return;
    if (reportNames.has(name)) { frappe.set_route("query-report", name); return; }
    if (singleDocs.has(name)) { frappe.set_route("Form", name); return; }
    frappe.set_route("List", name);
  }


  /* ─────────────────────────────────────────
     ١٥. أحداث الضغط
  ───────────────────────────────────────── */

  let lastToggleTime = 0;

  content.addEventListener("click", (event) => {
    const infoBtn = event.target.closest("[data-info-item]");
    if (infoBtn) {
      event.preventDefault();
      event.stopPropagation();
      const itemName = infoBtn.dataset.infoItem;
      const desc = itemDescriptions[itemName];
      if (desc) {
        showInfoModal({
          icon: desc.icon || "📄",
          labelAr: translate(itemName),
          labelEn: itemName,
          summaryAr: desc.summaryAr,
          summaryEn: desc.summaryEn,
          stepsAr: desc.stepsAr,
          stepsEn: desc.stepsEn
        });
      }
      return;
    }

    const routeButton = event.target.closest("[data-route-name]");
    if (routeButton) {
      event.preventDefault();
      event.stopPropagation();
      openRoute(routeButton.dataset.routeName);
      return;
    }

    const cardButton = event.target.closest("[data-card-toggle]");
    if (!cardButton) return;

    const now = Date.now();
    if (now - lastToggleTime < 400) return;
    lastToggleTime = now;

    const selectedCard = cardButton.closest("[data-erp-card]");
    if (!selectedCard) return;

    const shouldOpen = !selectedCard.classList.contains("is-open");

    content.querySelectorAll("[data-erp-card]").forEach((card) => {
      if (card !== selectedCard) {
        card.classList.remove("is-open");
        card.querySelector("[data-card-toggle]")?.setAttribute("aria-expanded", "false");
      }
    });

    if (shouldOpen) {
      selectedCard.classList.add("is-open");
      cardButton.setAttribute("aria-expanded", "true");
    } else {
      selectedCard.classList.remove("is-open");
      cardButton.setAttribute("aria-expanded", "false");
    }
  });


  /* ─────────────────────────────────────────
     ١٦. تشغيل
  ───────────────────────────────────────── */

  renderQuickActions();
  renderSections();
  renderFooter();
})();

style:
/* ═══════════════════════════════════════════
   لوحة تحكم قسم المبيعات — ERPNext Workspace
   ═══════════════════════════════════════════

   الأقسام:
     ١. الحاوية الرئيسية
     ٢. خلفية الشعار
     ٣. الشعار العلوي
     ٤. بطاقات الإحصائيات  ← جديد
     ٥. أزرار الاختصارات    ← جديد
     ٦. عنوان القسم
     ٧. شبكة البطاقات (التقارير)
     ٨. البطاقة (مغلقة / مفتوحة)
     ٩. ألوان البطاقات
     ١٠. عنوان البطاقة
     ١١. أيقونة البطاقة
     ١٢. اسم البطاقة
     ١٣. الخيارات
     ١٤. زر الخيار
     ١٥. شريط التمرير
     ١٦. الفوتر           ← جديد
     ١٧. الوضع الليلي
     ١٨. التابلت
     ١٩. الجوال
═══════════════════════════════════════════ */


/* =========================
   ١. الحاوية الرئيسية
========================= */

.erp-dashboard-wrapper {
  position: relative;
  width: 100%;
  padding: 12px 16px 40px;
  overflow: visible;
  color: var(--text-color, #1f2937);
}

.erp-dashboard-wrapper,
.erp-dashboard-wrapper * {
  box-sizing: border-box;
  font-family:
    "Tajawal",
    "Inter",
    Arial,
    sans-serif !important;
}

/* اتجاه عربي */
.erp-dashboard-wrapper.erp-dashboard-rtl {
  direction: rtl;
  text-align: right;
}


/* =========================
   ٢. خلفية الشعار
========================= */

.erp-dashboard-bg {
  position: absolute;
  inset: 110px 0 0;
  width: 100%;
  height: calc(100% - 110px);
  object-fit: contain;
  object-position: center;
  opacity: 0.035;
  pointer-events: none;
  user-select: none;
  z-index: 0;
}


/* =========================
   ٣. الشعار العلوي
========================= */

.erp-dashboard-header {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 125px;
  padding: 18px 10px;
  margin-bottom: 4px;
  border-bottom: 1px solid
    var(--border-color, #e5e7eb);
}

.erp-dashboard-logo {
  display: block;
  width: min(300px, 72%);
  height: auto;
  object-fit: contain;
}

.erp-dashboard-content {
  position: relative;
  z-index: 2;
}


/* =========================
   ٤. بطاقات الإحصائيات
   (تظهر تحت الشعار مباشرة)
========================= */

/*
 * الشبكة: ٤ بطاقات في صف واحد.
 */
.erp-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin: 20px 0 8px;
}

/*
 * بطاقة الإحصائية الواحدة.
 * --stat-color يُعرّف من JS لكل بطاقة.
 */
.erp-stat-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;

  border-radius: 14px;
  border: 1px solid var(--border-color, #e5e7eb);

  background:
    var(--card-bg, var(--fg-color, #ffffff));

  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.05);

  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}

/* تأثير عند تمرير الماوس على بطاقة الإحصائية */
@media (hover: hover) {
  .erp-stat-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  }
}

/*
 * أيقونة الإحصائية (إيموجي).
 */
.erp-stat-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 44px;
  height: 44px;
  flex: 0 0 44px;

  border-radius: 12px;

  background: color-mix(
    in srgb,
    var(--stat-color) 12%,
    transparent
  );

  font-size: 22px;
}

/*
 * معلومات الإحصائية (القيمة + التسمية).
 */
.erp-stat-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

/*
 * القيمة الرقمية.
 */
.erp-stat-value {
  font-size: 18px;
  font-weight: 800;
  color: var(--stat-color);
  line-height: 1.3;
  direction: ltr;
}

/*
 * تسمية الإحصائية.
 */
.erp-stat-label {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-muted, #6b7280);
  line-height: 1.4;
}


/* =========================
   ٥. أزرار الاختصارات السريعة
   (تظهر تحت بطاقات الإحصائيات)
========================= */

/*
 * شبكة الأزرار: ٤ أزرار في صف واحد.
 */
.erp-quick-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

/*
 * زر الاختصار الواحد.
 * --btn-color يُعرّف من JS لكل زر.
 */
.erp-quick-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  padding: 12px 16px;

  border: 1px solid
    color-mix(in srgb, var(--btn-color) 30%, transparent);
  border-radius: 12px;
  outline: none;

  background:
    color-mix(in srgb, var(--btn-color) 8%, transparent);

  color: var(--btn-color);

  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.4;
  text-align: center;

  cursor: pointer;

  transition:
    transform 0.2s ease,
    background-color 0.2s ease,
    box-shadow 0.2s ease;
}

/* تأثير عند تمرير الماوس */
@media (hover: hover) {
  .erp-quick-btn:hover {
    background:
      color-mix(in srgb, var(--btn-color) 15%, transparent);
    transform: translateY(-2px);
    box-shadow: 0 6px 16px
      color-mix(in srgb, var(--btn-color) 20%, transparent);
  }
}

/* تأثير عند الضغط */
.erp-quick-btn:active {
  transform: scale(0.97);
}

/*
 * أيقونة زر الاختصار.
 */
.erp-quick-icon {
  font-size: 18px;
  line-height: 1;
}

/*
 * تسمية زر الاختصار.
 */
.erp-quick-label {
  white-space: nowrap;
}


/* =========================
   ٦. عنوان القسم
========================= */

.erp-module-section {
  margin-top: 26px;
}

.erp-section-title {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 34px;
  margin: 0 0 14px;
  padding: 0 0 8px;
  border-bottom: 1px solid
    var(--border-color, #e5e7eb);
  color: var(--text-color, #1f2937);
  font-size: 16px;
  font-weight: 800;
}

/* الخط البنفسجي تحت العنوان */
.erp-section-title::after {
  content: "";
  position: absolute;
  bottom: -1px;
  width: 50px;
  height: 2px;
  border-radius: 20px;
  background: #644ca6;
}

/* موضع الخط في العربية */
.erp-dashboard-rtl
.erp-section-title::after {
  right: 0;
}

/* موضع الخط في الإنجليزية */
.erp-dashboard-wrapper:not(
  .erp-dashboard-rtl
)
.erp-section-title::after {
  left: 0;
}


/* =========================
   ٧. شبكة بطاقات التقارير
========================= */

.erp-dashboard-grid {
  display: grid !important;
  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;
  align-items: start;
  gap: 16px;
  overflow: visible;
}


/* =========================
   ٨. البطاقة وهي مغلقة
========================= */

.erp-card {
  --erp-accent: #2563eb;
  --erp-soft: rgba(37, 99, 235, 0.075);

  position: relative;
  z-index: 1;
  min-width: 0;

  /* حجم البطاقة قبل فتحها */
  min-height: 76px;
  max-height: 76px;

  padding: 0 16px;
  overflow: hidden;

  border: 1px solid
    var(--border-color, #e5e7eb);
  border-radius: 16px;

  background:
    var(--card-bg, var(--fg-color, #ffffff));

  box-shadow:
    0 5px 16px rgba(15, 23, 42, 0.06);

  transition:
    max-height 0.45s ease,
    transform 0.3s cubic-bezier(.4, 0, .2, 1),
    box-shadow 0.3s cubic-bezier(.4, 0, .2, 1),
    border-color 0.3s ease,
    padding-bottom 0.3s ease;
}

/* خلفية خفيفة للبطاقة (تظهر عند الفتح) */
.erp-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--erp-soft);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

/* الخط الملون أسفل البطاقة */
.erp-card::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  z-index: 4;
  width: 0;
  height: 4px;
  background: var(--erp-accent);
  transition: width 0.35s ease;
}

/* اتجاه الخط في الإنجليزية */
.erp-dashboard-wrapper:not(
  .erp-dashboard-rtl
)
.erp-card::after {
  right: auto;
  left: 0;
}


/* =========================
   ٨-أ. فتح البطاقة — is-open (يعمل دائماً)
========================= */

.erp-card.is-open {
  z-index: 30;
  max-height: 590px;
  padding-bottom: 16px;
  border-color: var(--erp-accent);
  transform: translateY(-7px) scale(1.025);
  box-shadow: 0 22px 48px rgba(15, 23, 42, 0.17);
}

.erp-card.is-open::before {
  opacity: 1;
}

.erp-card.is-open::after {
  width: 100%;
}


/* =========================
   ٨-ب. فتح البطاقة — hover (ماوس فقط)
   مغلّف بـ @media (hover: hover) لمنع
   مشكلة "اللصق" على الجوال/التابلت.
========================= */

@media (hover: hover) {
  .erp-card:hover,
  .erp-card:focus-within {
    z-index: 30;
    max-height: 590px;
    padding-bottom: 16px;
    border-color: var(--erp-accent);
    transform: translateY(-7px) scale(1.025);
    box-shadow: 0 22px 48px rgba(15, 23, 42, 0.17);
  }

  .erp-card:hover::before,
  .erp-card:focus-within::before {
    opacity: 1;
  }

  .erp-card:hover::after,
  .erp-card:focus-within::after {
    width: 100%;
  }
}


/* =========================
   ٩. ألوان البطاقات
========================= */

.erp-card.tone-0 {
  --erp-accent: #2563eb;
  --erp-soft: rgba(37, 99, 235, 0.075);
}

.erp-card.tone-1 {
  --erp-accent: #16a34a;
  --erp-soft: rgba(22, 163, 74, 0.075);
}

.erp-card.tone-2 {
  --erp-accent: #ea580c;
  --erp-soft: rgba(234, 88, 12, 0.075);
}

.erp-card.tone-3 {
  --erp-accent: #dc2626;
  --erp-soft: rgba(220, 38, 38, 0.075);
}

.erp-card.tone-4 {
  --erp-accent: #7c3aed;
  --erp-soft: rgba(124, 58, 237, 0.075);
}


/* =========================
   ١٠. عنوان البطاقة
========================= */

.erp-card-heading {
  position: relative;
  z-index: 2;

  display: flex;
  align-items: center;
  gap: 11px;

  width: 100%;
  height: 74px;

  margin: 0;
  padding: 0;

  border: 0;
  border-bottom: 1px solid transparent;
  outline: none;

  background: transparent;
  color: inherit;
  text-align: inherit;
  cursor: pointer;

  transition:
    border-color 0.25s ease,
    margin-bottom 0.25s ease;
}

/* عند فتح البطاقة يظهر خط فاصل */
.erp-card.is-open
.erp-card-heading {
  margin-bottom: 10px;
  border-bottom-color:
    var(--border-color, #e5e7eb);
}

@media (hover: hover) {
  .erp-card:hover .erp-card-heading,
  .erp-card:focus-within .erp-card-heading {
    margin-bottom: 10px;
    border-bottom-color:
      var(--border-color, #e5e7eb);
  }
}


/* =========================
   ١١. أيقونة البطاقة
========================= */

.erp-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 38px;
  height: 38px;
  flex: 0 0 38px;

  border-radius: 12px;

  background: var(--erp-soft);
  color: var(--erp-accent);

  font-size: 21px;
  line-height: 1;

  transition: transform 0.25s ease;
}

/* تكبير الأيقونة عند فتح البطاقة */
.erp-card.is-open .erp-icon {
  transform: scale(1.1) rotate(-3deg);
}

@media (hover: hover) {
  .erp-card:hover .erp-icon,
  .erp-card:focus-within .erp-icon {
    transform: scale(1.1) rotate(-3deg);
  }
}


/* =========================
   ١٢. اسم البطاقة وسهم الفتح
========================= */

.erp-card-title {
  flex: 1;
  min-width: 0;
  margin: 0;
  color: var(--text-color, #1f2937);
  font-size: 15px;
  font-weight: 800;
  line-height: 1.5;
}

/* سهم فتح البطاقة (⌄) */
.erp-card-chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 25px;
  height: 25px;
  border-radius: 8px;

  background: var(--erp-soft);
  color: var(--erp-accent);

  font-size: 17px;
  transition: transform 0.25s ease;
}

/* دوران السهم عند الفتح */
.erp-card.is-open .erp-card-chevron {
  transform: rotate(180deg);
}

@media (hover: hover) {
  .erp-card:hover .erp-card-chevron,
  .erp-card:focus-within .erp-card-chevron {
    transform: rotate(180deg);
  }
}


/* =========================
   ١٣. الخيارات (مخفية افتراضيًا)
========================= */

.erp-card-links {
  position: relative;
  z-index: 2;

  display: grid;
  gap: 6px;

  max-height: 0;
  margin: 0;
  padding: 0;

  overflow: hidden;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;

  transform: translateY(-12px);

  transition:
    max-height 0.42s ease,
    opacity 0.22s ease,
    visibility 0.22s ease,
    transform 0.3s ease;
}

/* إظهار الخيارات عند فتح البطاقة */
.erp-card.is-open .erp-card-links {
  max-height: 480px;
  overflow-y: auto;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

@media (hover: hover) {
  .erp-card:hover .erp-card-links,
  .erp-card:focus-within .erp-card-links {
    max-height: 480px;
    overflow-y: auto;
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: translateY(0);
  }
}


/* =========================
   ١٤. زر الخيار
========================= */

.erp-link {
  display: flex;
  align-items: center;
  gap: 9px;

  width: 100%;
  min-height: 35px;
  padding: 7px 10px;

  border: 1px solid transparent;
  border-radius: 9px;
  outline: none;

  background: transparent;
  color: var(--text-color, #374151);

  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.45;
  text-align: inherit;

  cursor: pointer;

  transition:
    transform 0.17s ease,
    border-color 0.17s ease,
    background-color 0.17s ease,
    color 0.17s ease;
}

/* إبراز الخيار */
.erp-link:hover,
.erp-link:focus {
  border-color: rgba(100, 76, 166, 0.3);
  background: var(--erp-soft);
  color: var(--erp-accent);
}

/* حركة الرابط — عربي */
.erp-dashboard-rtl .erp-link:hover,
.erp-dashboard-rtl .erp-link:focus {
