}

/* حركة الرابط — إنجليزي */
.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:hover,
.erp-dashboard-wrapper:not(.erp-dashboard-rtl)
.erp-link:focus {
  transform: translateX(4px);
}

.erp-link-text {
