  min-width: 0;
}

/* سهم الخيار */
.erp-link-arrow {
  flex: 0 0 auto;
  color: var(--erp-accent);
  font-size: 14px;
  font-weight: 800;
  opacity: 0;
  transform: translateX(-4px);
  transition:
    opacity 0.17s ease,
    transform 0.17s ease;
}

.erp-link:hover .erp-link-arrow,
.erp-link:focus .erp-link-arrow {
  opacity: 1;
  transform: translateX(0);
}


/* =========================
   ١٥. شريط تمرير الخيارات
========================= */

.erp-card-links::-webkit-scrollbar {
