    padding: 10px 8px;
    font-size: 12px;
    min-height: 44px;
    justify-content: center;
    text-align: center;
  }

  /* تصغير أيقونة الاختصار على الجوال */
  .erp-quick-icon {
    font-size: 16px;
  }

  /* السماح بالتفاف النص داخل الزر */
