  }

  /* إخفاء الفواصل على الجوال */
  .erp-footer-sep {
    display: none;
  }
}
/* =========================
   ٢٠. صف الرابط + زر التفاصيل داخل البطاقة
========================= */

.erp-link-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.erp-link-row .erp-link {
  flex: 1;
}

.erp-info-link {
  flex: 0 0 auto;
  padding: 4px 10px;
  border: 1px solid rgba(100, 76, 166, 0.25);
  border-radius: 6px;
  outline: none;
  background: rgba(100, 76, 166, 0.08);
  color: #644ca6;
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease;
}

.erp-info-link:hover {
  background: rgba(100, 76, 166, 0.18);
}


/* =========================
   ٢١. مربع التفاصيل (Modal)
========================= */

/*
 * خلفية المربع الداكنة — تغطي كامل الشاشة.
 * z-index عالي جداً لضمان ظهوره فوق كل شيء.
 * !important لمنع تداخل ستايلات الورك سبيس.
 */
.erp-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999 !important;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 20px;

  background: rgba(0, 0, 0, 0) !important;

  font-family:
    "Tajawal",
    "Inter",
    Arial,
    sans-serif !important;

  transition: background 0.3s ease;
}

/* ظهور الخلفية الداكنة */
.erp-modal-overlay.is-visible {
  background: rgba(0, 0, 0, 0.55) !important;
}

/*
 * صندوق المربع الأبيض.
 * خلفية بيضاء صلبة وظل قوي للبروز.
 */
.erp-modal-box {
  position: relative;

  width: 100%;
  max-width: 480px;
  max-height: 85vh;

  padding: 28px 24px;

  overflow-y: auto;

  border-radius: 18px;

  background: #ffffff !important;

  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.35) !important;

  opacity: 0;
  transform: translateY(30px) scale(0.95);

  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

/* أنيميشن الظهور */
.erp-modal-overlay.is-visible .erp-modal-box {
  opacity: 1;
  transform: translateY(0) scale(1);
}

/*
 * زر الإغلاق ✕ في الزاوية.
 */
.erp-modal-close {
  position: absolute;
  top: 12px;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 32px;
  height: 32px;

  border: none;
  border-radius: 8px;
  outline: none;

  background: #f3f4f6;

  color: #6b7280;
  font-size: 16px;
  cursor: pointer;

  transition:
    background-color 0.2s ease,
    color 0.2s ease;
}

/* موضع زر الإغلاق حسب اتجاه اللغة */
[dir="rtl"] .erp-modal-close {
  left: 12px;
}

[dir="ltr"] .erp-modal-close {
  right: 12px;
}

.erp-modal-close:hover {
  background: #e5e7eb;
  color: #1f2937;
}

/*
 * رأس المربع — أيقونة + عنوان.
 */
.erp-modal-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
}

.erp-modal-icon {
  font-size: 32px;
  line-height: 1;
}

.erp-modal-title {
  margin: 0;
  font-size: 18px;
  font-weight: 800;
  color: #1f2937 !important;
  line-height: 1.4;
}

/*
 * الوصف المختصر.
 */
.erp-modal-summary {
  margin: 0 0 16px;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1.7;
  color: #1f2937 !important;
}

/*
 * زر عرض/إخفاء الخطوات.
 */
.erp-modal-toggle-steps {
  display: inline-flex;
  align-items: center;
  gap: 6px;

  padding: 8px 18px;

  border: 1px solid #644ca6;
  border-radius: 10px;
  outline: none;

  background: rgba(100, 76, 166, 0.08);

  color: #644ca6;

  font-family: inherit;
  font-size: 13px;
  font-weight: 700;

  cursor: pointer;

  transition:
    background-color 0.2s ease,
    transform 0.15s ease;
}

.erp-modal-toggle-steps:hover {
  background: rgba(100, 76, 166, 0.15);
}

.erp-modal-toggle-steps:active {
  transform: scale(0.97);
}

/*
 * حاوية الخطوات — مخفية افتراضياً.
 */
.erp-modal-steps {
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  margin-top: 0;

  transition:
    max-height 0.4s ease,
    opacity 0.3s ease,
    margin-top 0.3s ease;
}

/* إظهار الخطوات عند الضغط */
.erp-modal-steps.is-shown {
  max-height: 500px;
  opacity: 1;
  margin-top: 16px;
}

/*
 * قائمة الخطوات المرقّمة.
 */
.erp-modal-steps-list {
  margin: 0;
  padding: 0 20px;
  list-style: none;
  counter-reset: step-counter;
}

.erp-modal-steps-list li {
  position: relative;
  counter-increment: step-counter;

  padding: 10px 0 10px 8px;

  border-bottom: 1px solid #f0f0f0;

  font-size: 13px;
  font-weight: 500;
  line-height: 1.6;
  color: #374151 !important;
}

/* RTL: تعديل padding */
[dir="rtl"] .erp-modal-steps-list li {
  padding: 10px 8px 10px 0;
}

/* آخر عنصر بدون خط فاصل */
.erp-modal-steps-list li:last-child {
  border-bottom: none;
}

/* رقم الخطوة كدائرة ملونة */
.erp-modal-steps-list li::before {
  content: counter(step-counter);

  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 22px;
  height: 22px;

  margin-inline-end: 10px;

  border-radius: 50%;

  background: #644ca6;
  color: #fff;

  font-size: 11px;
  font-weight: 800;

  vertical-align: middle;
}

/* =========================
   ٢٢. الوضع الليلي — Modal
========================= */

[data-theme="dark"] .erp-modal-box,
html[data-theme="dark"] .erp-modal-box {
  background: var(--fg-color, #20242c);
}

[data-theme="dark"] .erp-modal-close,
html[data-theme="dark"] .erp-modal-close {
  background: rgba(255, 255, 255, 0.08);
  color: #d1d5db;
}

[data-theme="dark"] .erp-modal-toggle-steps,
html[data-theme="dark"] .erp-modal-toggle-steps {
  background: rgba(100, 76, 166, 0.2);
  border-color: #7c3aed;
  color: #a78bfa;
}


/* =========================
   ٢٣. الجوال — Modal + أيقونة المعلومات
========================= */

@media (max-width: 650px) {
  /* تصغير أيقونة المعلومات على الجوال */
  .erp-quick-info {
    width: 32px;
    flex: 0 0 32px;
    font-size: 13px;
  }

  /* تصغير المربع على الجوال */
  .erp-modal-overlay {
    padding: 12px;
    align-items: flex-end;
  }

  .erp-modal-box {
    max-height: 80vh;
    padding: 22px 18px;
    border-radius: 18px 18px 0 0;
  }

  .erp-modal-title {
    font-size: 16px;
  }

  .erp-modal-summary {
    font-size: 13px;
  }

  /* الأزرار داخل wrapper على الجوال */
  .erp-quick-wrapper .erp-quick-btn {
    padding: 10px 8px;
    font-size: 12px;
    min-height: 44px;
    justify-content: center;
    text-align: center;
  }

  .erp-quick-wrapper .erp-quick-icon {
    font-size: 16px;
  }

  .erp-quick-wrapper .erp-quick-label {
    white-space: normal;
    line-height: 1.3;
  }
}

